UPDATE master_beast_gen SET freq = freq + (SELECT SUM(n.freq - 1) FROM master_beast_gen n WHERE n.id = master_beast_gen.id AND CASE n.bstid WHEN 'BST_SCORPION02' THEN 'BST_GSCORPION' WHEN 'BST_BASS02' THEN 'BST_GBASS' ELSE 'BST_G' || substr(n.bstid, 5) END = master_beast_gen.bstid AND substr(n.bstid, 1, 5) <> 'BST_G') WHERE substr(bstid, 1, 5) = 'BST_G' AND EXISTS (SELECT 1 FROM master_beast_gen n WHERE n.id = master_beast_gen.id AND CASE n.bstid WHEN 'BST_SCORPION02' THEN 'BST_GSCORPION' WHEN 'BST_BASS02' THEN 'BST_GBASS' ELSE 'BST_G' || substr(n.bstid, 5) END = master_beast_gen.bstid AND substr(n.bstid, 1, 5) <> 'BST_G');
INSERT OR IGNORE INTO master_beast_gen (id, bstid, freq) SELECT id, twin, MAX(1, SUM(freq - 1)) FROM (SELECT id, freq, CASE bstid WHEN 'BST_SCORPION02' THEN 'BST_GSCORPION' WHEN 'BST_BASS02' THEN 'BST_GBASS' ELSE 'BST_G' || substr(bstid, 5) END AS twin FROM master_beast_gen WHERE substr(bstid, 1, 5) <> 'BST_G') WHERE twin IN (SELECT id FROM master_beast) GROUP BY id, twin;
UPDATE master_beast_gen SET freq = 1 WHERE substr(bstid, 1, 5) <> 'BST_G' AND (CASE bstid WHEN 'BST_SCORPION02' THEN 'BST_GSCORPION' WHEN 'BST_BASS02' THEN 'BST_GBASS' ELSE 'BST_G' || substr(bstid, 5) END) IN (SELECT id FROM master_beast);
